// Deterministic spoken briefing. Every number comes from the fetched report; nothing is generated by a model.
import type { ChannelReport, Comparison } from '../../shared/types';

const MONTHS = ['January', 'February', 'March', 'April', 'May', 'June', 'July', 'August', 'September', 'October', 'November', 'December'];
export const sayDate = (isoDay: string): string => {
  const [, m, d] = isoDay.slice(0, 10).split('-').map(Number);
  return `${MONTHS[m - 1]} ${d}`;
};
export const sayNumber = (n: number): string => Math.round(n).toLocaleString('en-US');

/** The Data API rounds subscriber totals down to three significant figures, so say "about". */
export function saySubscribers(report: ChannelReport): string {
  const c = report.channel;
  if (c.hiddenSubscriberCount || c.subscriberCountRounded === null) return 'Your subscriber count is hidden, so I can’t read it.';
  return `You have about ${sayNumber(c.subscriberCountRounded)} subscribers. YouTube rounds that figure down.`;
}

export function sayWatchTime(minutes: number): string {
  if (minutes < 90) return `${sayNumber(minutes)} minutes`;
  const h = minutes / 60;
  return `${h < 100 ? (Math.round(h * 10) / 10).toLocaleString('en-US') : sayNumber(h)} hours`;
}

function sayPeriod(label: string, c: Comparison): string {
  const cur = c.current;
  const parts: string[] = [];
  const partial = cur.complete ? '' : ` across the ${cur.days - cur.missingDays.length} days that have data`;
  parts.push(`In the ${label} ending ${sayDate(cur.end)}${partial}, you had ${sayNumber(cur.views)} views and ${sayWatchTime(cur.minutesWatched)} of watch time.`);
  if (c.viewsChangePct !== null) {
    const p = Math.abs(c.viewsChangePct);
    parts.push(c.viewsChangePct === 0 ? `Views were level with the ${cur.days} days before.` : `Views were ${c.viewsChangePct > 0 ? 'up' : 'down'} ${p} percent on the ${cur.days} days before.`);
  }
  const net = cur.netSubs;
  parts.push(net === 0 ? 'Subscribers were flat for that period.' : `You ${net > 0 ? 'gained' : 'lost'} a net ${sayNumber(Math.abs(net))} subscriber${Math.abs(net) === 1 ? '' : 's'} in that period.`);
  return parts.join(' ');
}

export function narrate(report: ChannelReport, opts: { stale: boolean; now?: Date } = { stale: false }): string {
  const out: string[] = [];
  out.push(`Here’s your briefing for ${report.channel.title}.`);
  if (opts.stale) out.push(`I couldn’t refresh just now, so these are saved figures from ${sayDate(report.fetchedAt)}.`);
  out.push(saySubscribers(report));
  if (report.last7) out.push(sayPeriod('seven days', report.last7));
  if (report.last28) out.push(sayPeriod('28 days', report.last28));
  if (!report.last7 && !report.last28) out.push('YouTube Analytics has not returned any daily data yet, so I have no view figures to report.');
  const top = report.topVideos28[0];
  if (top && top.views > 0) out.push(`Your strongest video over those 28 days was ${top.title}, with ${sayNumber(top.views)} views.`);
  if (report.latestDataDate) out.push(`Analytics are complete through ${sayDate(report.latestDataDate)}; later days are still processing.`);
  return out.join(' ');
}

/** Short answers for direct questions, still without a model call. */
export function answerSubscribers(report: ChannelReport, stale: boolean): string {
  const base = saySubscribers(report);
  const n = report.last28?.current;
  const extra = n ? ` Over the 28 days to ${sayDate(n.end)} the net change was ${n.netSubs >= 0 ? 'plus' : 'minus'} ${sayNumber(Math.abs(n.netSubs))}.` : '';
  return (stale ? 'From saved figures: ' : '') + base + extra;
}

export type LocalIntent = 'briefing' | 'subscribers' | null;
/** Recognise the channel questions that are answered from fetched data instead of a Claude call. */
export function detectIntent(text: string): LocalIntent {
  const t = text.toLowerCase().replace(/[^a-z0-9' ]+/g, ' ').replace(/\s+/g, ' ').trim();
  if (t.length > 90) return null;
  if (/\bhow many (subs|subscribers)\b/.test(t) || /\b(subscriber|sub) count\b/.test(t)) return 'subscribers';
  if (/\b(channel|youtube|analytics) (briefing|brief|update|report|stats|numbers)\b/.test(t) || /\bhow('s| is) (my|the) channel\b/.test(t) || /\bhow (is|are) my (channel|videos|views)\b.*\bdoing\b/.test(t) || /^(give me )?(my |a |the )?briefing( please)?$/.test(t)) return 'briefing';
  return null;
}
